export const officialOfferHtml = "\n<div class=\"page-content\">\n<div data-elementor-type=\"wp-page\" data-elementor-id=\"1078\" class=\"elementor elementor-1078\">\n<section class=\"elementor-section elementor-top-section elementor-element elementor-element-7cf201b elementor-section-height-min-height elementor-section-boxed elementor-section-height-default elementor-section-items-middle\" data-id=\"7cf201b\" data-element_type=\"section\" data-settings=\"{&quot;background_background&quot;:&quot;classic&quot;}\">\n<div class=\"elementor-background-overlay\"></div>\n<div class=\"elementor-container elementor-column-gap-default\">\n<div class=\"elementor-column elementor-col-100 elementor-top-column elementor-element elementor-element-f06669b\" data-id=\"f06669b\" data-element_type=\"column\">\n<div class=\"elementor-widget-wrap elementor-element-populated\">\n<div class=\"elementor-element elementor-element-515213b elementor-widget elementor-widget-heading\" data-id=\"515213b\" data-element_type=\"widget\" data-widget_type=\"heading.default\">\n<div class=\"elementor-widget-container\">\n<style>/*! elementor - v3.11.5 - 14-03-2023 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h1 class=\"elementor-heading-title elementor-size-default\">Oferta</h1>\t\t</div>\n</div>\n</div>\n</div>\n</div>\n</section>\n<section class=\"elementor-section elementor-top-section elementor-element elementor-element-ea0c9d4 elementor-section-boxed elementor-section-height-default elementor-section-height-default\" data-id=\"ea0c9d4\" data-element_type=\"section\">\n<div class=\"elementor-container elementor-column-gap-default\">\n<div class=\"elementor-column elementor-col-100 elementor-top-column elementor-element elementor-element-6a180d3\" data-id=\"6a180d3\" data-element_type=\"column\">\n<div class=\"elementor-widget-wrap elementor-element-populated\">\n<div class=\"elementor-element elementor-element-09b3f59 elementor-widget elementor-widget-html\" data-id=\"09b3f59\" data-element_type=\"widget\" data-widget_type=\"html.default\">\n<div class=\"elementor-widget-container\">\n<style>\n@media only screen and (max-width: 768px) { \n/* For mobile phones: */ \n.button-oferta.pojedynczy a.elementor-button-link {\nwidth: 180px;\nheight: 70px;\n}\n}\na.eael-creative-button {text-decoration: none;}\n.elementor-inline-item {\nbackground-color: #006BA6;\npadding: 10px!important;\nmargin: 5px!important;\nborder-radius: 10px!important;\n}\n.elementor-inline-item:hover {\nbackground-color: #162736;\n}\n.elementor-icon-list-text {\ncolor: #fff!important;\n}\n</style>\n</div>\n</div>\n<div class=\"elementor-element elementor-element-76ebe20 elementor-icon-list--layout-inline elementor-align-center elementor-list-item-link-full_width elementor-widget elementor-widget-icon-list\" data-id=\"76ebe20\" data-element_type=\"widget\" data-widget_type=\"icon-list.default\">\n<div class=\"elementor-widget-container\">\n<!-- <link rel=\"stylesheet\" href=\"https://ptakstomatologia.pl/wp-content/plugins/elementor/assets/css/widget-icon-list.min.css\"> -->\n<link rel=\"stylesheet\" type=\"text/css\" href=\"//ptakstomatologia.pl/wp-content/cache/wpfc-minified/6mu5ubn9/hpxgu.css\" media=\"all\">\t\t<ul class=\"elementor-icon-list-items elementor-inline-items\">\n<li class=\"elementor-icon-list-item elementor-inline-item\">\n<a href=\"#stomatologia-zachowawcza\" class=\"__mPS2id _mPS2id-h\">\n<span class=\"elementor-icon-list-text\">Stomatologia <br>zachowawcza</span>\n</a>\n</li>\n<li class=\"elementor-icon-list-item elementor-inline-item\">\n<a href=\"#endodoncja-mikroskopowa\" class=\"__mPS2id _mPS2id-h\">\n<span class=\"elementor-icon-list-text\">Endodoncja <br>mikroskopowa</span>\n</a>\n</li>\n<li class=\"elementor-icon-list-item elementor-inline-item\">\n<a href=\"#chirurgia\" class=\"__mPS2id _mPS2id-h\">\n<span class=\"elementor-icon-list-text\">Chirurgia <br>stomatologiczna</span>\n</a>\n</li>\n<li class=\"elementor-icon-list-item elementor-inline-item\">\n<a href=\"#protetyka\" class=\"__mPS2id _mPS2id-h\">\n<span class=\"elementor-icon-list-text\">Protetyka</span>\n</a>\n</li>\n<li class=\"elementor-icon-list-item elementor-inline-item\">\n<a href=\"#implantologia\" class=\"__mPS2id _mPS2id-h\">\n<span class=\"elementor-icon-list-text\">Implantologia</span>\n</a>\n</li>\n<li class=\"elementor-icon-list-item elementor-inline-item\">\n<a href=\"#ortodoncja\" class=\"__mPS2id _mPS2id-h\">\n<span class=\"elementor-icon-list-text\">Ortodoncja</span>\n</a>\n</li>\n<li class=\"elementor-icon-list-item elementor-inline-item\">\n<a href=\"#stomatologia-estetyczna\" class=\"__mPS2id\">\n<span class=\"elementor-icon-list-text\">Stomatologia <br>estetyczna</span>\n</a>\n</li>\n<li class=\"elementor-icon-list-item elementor-inline-item\">\n<a href=\"#higienizacja\" class=\"__mPS2id _mPS2id-h\">\n<span class=\"elementor-icon-list-text\">Higienizacja</span>\n</a>\n</li>\n<li class=\"elementor-icon-list-item elementor-inline-item\">\n<a href=\"#nowoczesne-technologie\" class=\"__mPS2id _mPS2id-h\">\n<span class=\"elementor-icon-list-text\">Nowoczesne<br> technologie</span>\n</a>\n</li>\n</ul>\n</div>\n</div>\n<div class=\"elementor-element elementor-element-3e41698 elementor-widget elementor-widget-heading _mPS2id-t\" data-id=\"3e41698\" data-element_type=\"widget\" id=\"stomatologia-zachowawcza\" data-widget_type=\"heading.default\">\n<div class=\"elementor-widget-container\">\n<h3 class=\"elementor-heading-title elementor-size-default\">Stomatologia zachowawcza</h3>\t\t</div>\n</div>\n<div class=\"elementor-element elementor-element-b596052 elementor-widget-divider--view-line_icon elementor-view-default elementor-widget-divider--element-align-center elementor-widget elementor-widget-divider\" data-id=\"b596052\" data-element_type=\"widget\" data-widget_type=\"divider.default\">\n<div class=\"elementor-widget-container\">\n<style>/*! elementor - v3.11.5 - 14-03-2023 */\n.elementor-widget-divider{--divider-border-style:none;--divider-border-width:1px;--divider-color:#2c2c2c;--divider-icon-size:20px;--divider-element-spacing:10px;--divider-pattern-height:24px;--divider-pattern-size:20px;--divider-pattern-url:none;--divider-pattern-repeat:repeat-x}.elementor-widget-divider .elementor-divider{display:flex}.elementor-widget-divider .elementor-divider__text{font-size:15px;line-height:1;max-width:95%}.elementor-widget-divider .elementor-divider__element{margin:0 var(--divider-element-spacing);flex-shrink:0}.elementor-widget-divider .elementor-icon{font-size:var(--divider-icon-size)}.elementor-widget-divider .elementor-divider-separator{display:flex;margin:0;direction:ltr}.elementor-widget-divider--view-line_icon .elementor-divider-separator,.elementor-widget-divider--view-line_text .elementor-divider-separator{align-items:center}.elementor-widget-divider--view-line_icon .elementor-divider-separator:after,.elementor-widget-divider--view-line_icon .elementor-divider-separator:before,.elementor-widget-divider--view-line_text .elementor-divider-separator:after,.elementor-widget-divider--view-line_text .elementor-divider-separator:before{display:block;content:\"\";border-bottom:0;flex-grow:1;border-top:var(--divider-border-width) var(--divider-border-style) var(--divider-color)}.elementor-widget-divider--element-align-left .elementor-divider .elementor-divider-separator>.elementor-divider__svg:first-of-type{flex-grow:0;flex-shrink:100}.elementor-widget-divider--element-align-left .elementor-divider-separator:before{content:none}.elementor-widget-divider--element-align-left .elementor-divider__element{margin-left:0}.elementor-widget-divider--element-align-right .elementor-divider .elementor-divider-separator>.elementor-divider__svg:last-of-type{flex-grow:0;flex-shrink:100}.elementor-widget-divider--element-align-right .elementor-divider-separator:after{content:none}.elementor-widget-divider--element-align-right .elementor-divider__element{margin-right:0}.elementor-widget-divider:not(.elementor-widget-divider--view-line_text):not(.elementor-widget-divider--view-line_icon) .elementor-divider-separator{border-top:var(--divider-border-width) var(--divider-border-style) var(--divider-color)}.elementor-widget-divider--separator-type-pattern{--divider-border-style:none}.elementor-widget-divider--separator-type-pattern.elementor-widget-divider--view-line .elementor-divider-separator,.elementor-widget-divider--separator-type-pattern:not(.elementor-widget-divider--view-line) .elementor-divider-separator:after,.elementor-widget-divider--separator-type-pattern:not(.elementor-widget-divider--view-line) .elementor-divider-separator:before,.elementor-widget-divider--separator-type-pattern:not([class*=elementor-widget-divider--view]) .elementor-divider-separator{width:100%;min-height:var(--divider-pattern-height);-webkit-mask-size:var(--divider-pattern-size) 100%;mask-size:var(--divider-pattern-size) 100%;-webkit-mask-repeat:var(--divider-pattern-repeat);mask-repeat:var(--divider-pattern-repeat);background-color:var(--divider-color);-webkit-mask-image:var(--divider-pattern-url);mask-image:var(--divider-pattern-url)}.elementor-widget-divider--no-spacing{--divider-pattern-size:auto}.elementor-widget-divider--bg-round{--divider-pattern-repeat:round}.rtl .elementor-widget-divider .elementor-divider__text{direction:rtl}.e-con-inner>.elementor-widget-divider,.e-con>.elementor-widget-divider{width:var(--container-widget-width,100%);--flex-grow:var(--container-widget-flex-grow)}</style>\t\t<div class=\"elementor-divider\">\n<span class=\"elementor-divider-separator\">\n<div class=\"elementor-icon elementor-divider__element\">\n<i aria-hidden=\"true\" class=\"fas fa-tooth\"></i></div>\n</span>\n</div>\n</div>\n</div>\n<div class=\"elementor-element elementor-element-d616138 elementor-widget elementor-widget-text-editor\" data-id=\"d616138\" data-element_type=\"widget\" data-widget_type=\"text-editor.default\">\n<div class=\"elementor-widget-container\">\n<style>/*! elementor - v3.11.5 - 14-03-2023 */\n.elementor-widget-text-editor.elementor-drop-cap-view-stacked .elementor-drop-cap{background-color:#818a91;color:#fff}.elementor-widget-text-editor.elementor-drop-cap-view-framed .elementor-drop-cap{color:#818a91;border:3px solid;background-color:transparent}.elementor-widget-text-editor:not(.elementor-drop-cap-view-default) .elementor-drop-cap{margin-top:8px}.elementor-widget-text-editor:not(.elementor-drop-cap-view-default) .elementor-drop-cap-letter{width:1em;height:1em}.elementor-widget-text-editor .elementor-drop-cap{float:left;text-align:center;line-height:1;font-size:50px}.elementor-widget-text-editor .elementor-drop-cap-letter{display:inline-block}</style>\t\t\t\t<p>Stomatologia zachowawcza zajmuje się rozpoznawaniem i leczeniem jednej z najbardziej powszechnej choroby zębów – próchnicy.</p><p>W naszym gabinecie stomatologicznym proponujemy Państwu wysokiej klasy wypełnienia estetyczne, które idealnie imitują naturalne, zdrowe zęby.</p>\t\t\t\t\t\t</div>\n</div>\n<div class=\"elementor-element elementor-element-0bc4a22 elementor-widget elementor-widget-heading _mPS2id-t\" data-id=\"0bc4a22\" data-element_type=\"widget\" id=\"endodoncja-mikroskopowa\" data-widget_type=\"heading.default\">\n<div class=\"elementor-widget-container\">\n<h3 class=\"elementor-heading-title elementor-size-default\">Endodoncja  mikroskopowa</h3>\t\t</div>\n</div>\n<div class=\"elementor-element elementor-element-65fba71 elementor-widget-divider--view-line_icon elementor-view-default elementor-widget-divider--element-align-center elementor-widget elementor-widget-divider\" data-id=\"65fba71\" data-element_type=\"widget\" data-widget_type=\"divider.default\">\n<div class=\"elementor-widget-container\">\n<div class=\"elementor-divider\">\n<span class=\"elementor-divider-separator\">\n<div class=\"elementor-icon elementor-divider__element\">\n<i aria-hidden=\"true\" class=\"fas fa-tooth\"></i></div>\n</span>\n</div>\n</div>\n</div>\n<div class=\"elementor-element elementor-element-f29ed0c elementor-widget elementor-widget-text-editor\" data-id=\"f29ed0c\" data-element_type=\"widget\" data-widget_type=\"text-editor.default\">\n<div class=\"elementor-widget-container\">\n<p>Endodoncja&nbsp;to dział stomatologii zajmujący się leczeniem chorób miazgi zęba oraz tkanek otaczających wierzchołek korzenia. Leczenie endodontyczne polega na usunięciu zainfekowanych tkanek, poszerzeniu światła kanału, zdezynfekowaniu i szczelnym wypełnieniu.</p><p><strong>Do leczenia endodontycznego wykorzystujemy:</strong></p><ul><li><strong>mikroskop stomatologiczny</strong> zapewniający dużą dokładność oraz przeprowadzenie procedur, które dawniej nie były osiągalne w endodoncji,</li><li><strong>rentgenodiagnostykę cyfrową,</strong> dzięki której weryfikujemy szybko poprawność przeprowadzonego leczenia,</li><li><strong>endometr</strong> służący do pomiaru długości kanału,</li><li><strong>wypełnienie kanału termiczną gutaperką,</strong> która pozwala na szczelne wypełnienie kanału i jego odgałęzień.</li></ul><p><strong>Zastosowanie mikroskopu w stomatologii:</strong></p><ul><li>odnalezienie i leczenie głównych oraz dodatkowych kanałów korzeniowych zęba wraz z ich rozgałęzieniami, które w tradycyjnym leczeniu często są niewidoczne dla lekarza, a przez to nie zostają opracowane i są przyczyna niepowodzenia leczenia,</li><li>usunięcie z kanału złamanych fragmentów narzędzi endodontycznych, wkładów koronowo – korzeniowych, twardych cementów wypełniających kanał zamknięcie perforacji korzenia zęba,</li><li>udrożnienie bardzo wąskich lub wręcz całkowicie zobliterowanych (zamkniętych) kanałów korzeniowych,</li><li>leczenie resorpcji korzeni zębów,</li><li>wykonanie skutecznego leczenia w przypadkach o bardzo skomplikowanej i rzadko występującej anatomii systemu kanałów korzeniowych,</li><li>mikrochirurgiczne resekcje wierzchołków korzeni zębów ze wstecznym ich wypełnieniem specjalnie do tego przeznaczonym materiałem.</li></ul>\t\t\t\t\t\t</div>\n</div>\n<div class=\"elementor-element elementor-element-33b5c7a elementor-widget elementor-widget-heading _mPS2id-t\" data-id=\"33b5c7a\" data-element_type=\"widget\" id=\"chirurgia\" data-widget_type=\"heading.default\">\n<div class=\"elementor-widget-container\">\n<h3 class=\"elementor-heading-title elementor-size-default\">Chirurgia stomatologiczna</h3>\t\t</div>\n</div>\n<div class=\"elementor-element elementor-element-531d146 elementor-widget-divider--view-line_icon elementor-view-default elementor-widget-divider--element-align-center elementor-widget elementor-widget-divider\" data-id=\"531d146\" data-element_type=\"widget\" data-widget_type=\"divider.default\">\n<div class=\"elementor-widget-container\">\n<div class=\"elementor-divider\">\n<span class=\"elementor-divider-separator\">\n<div class=\"elementor-icon elementor-divider__element\">\n<i aria-hidden=\"true\" class=\"fas fa-tooth\"></i></div>\n</span>\n</div>\n</div>\n</div>\n<div class=\"elementor-element elementor-element-29d4b16 elementor-widget elementor-widget-text-editor\" data-id=\"29d4b16\" data-element_type=\"widget\" data-widget_type=\"text-editor.default\">\n<div class=\"elementor-widget-container\">\n<p>Oferujemy pełen zakres świadczeń z zakresu chirurgii stomatologicznej.</p><p><strong>Zabiegi chirurgiczne, które są wykonywane najczęściej to:</strong></p><ul><li>usuwanie zębów, w tym zębów mądrości,</li><li>chirurgiczne usuwanie zębów zatrzymanych,</li><li>odsłonięcie zęba mądrości,</li><li>wydłużenie korony klinicznej,</li><li>resekcja korzeni zębów z wstecznym wypełnieniem MTA,</li><li>plastyka wędzidełka,</li><li>plastyka połączenia ustno – zatokowego,</li><li>plastyka wyrostka zębodołowego,</li><li>usuwanie torbieli (badanie histopatologiczne).</li></ul>\t\t\t\t\t\t</div>\n</div>\n<div class=\"elementor-element elementor-element-53599ae elementor-widget elementor-widget-heading _mPS2id-t\" data-id=\"53599ae\" data-element_type=\"widget\" id=\"protetyka\" data-widget_type=\"heading.default\">\n<div class=\"elementor-widget-container\">\n<h3 class=\"elementor-heading-title elementor-size-default\">Protetyka</h3>\t\t</div>\n</div>\n<div class=\"elementor-element elementor-element-61b28cb elementor-widget-divider--view-line_icon elementor-view-default elementor-widget-divider--element-align-center elementor-widget elementor-widget-divider\" data-id=\"61b28cb\" data-element_type=\"widget\" data-widget_type=\"divider.default\">\n<div class=\"elementor-widget-container\">\n<div class=\"elementor-divider\">\n<span class=\"elementor-divider-separator\">\n<div class=\"elementor-icon elementor-divider__element\">\n<i aria-hidden=\"true\" class=\"fas fa-tooth\"></i></div>\n</span>\n</div>\n</div>\n</div>\n<div class=\"elementor-element elementor-element-3badd59 elementor-widget elementor-widget-text-editor\" data-id=\"3badd59\" data-element_type=\"widget\" data-widget_type=\"text-editor.default\">\n<div class=\"elementor-widget-container\">\n<p>Odtwarza pierwotne warunki zgryzowe po utracie zębów naturalnych, po ich uszkodzeniu lub osłabieniu. Uzupełnienia protetyczne mogą być stałe, ruchome lub kombinowane (uzupełnienia ruchome połączone z uzupełnieniami stałymi za pomocą zasuw, zatrzasków).</p><div style=\"clear: both; padding-top: 20px; padding-bottom: 20px;\"><p style=\"text-align: center;\"><strong>Ruchome uzupełnienia protetyczne&nbsp;(czyli wyjmowane przez pacjenta):</strong></p><div style=\"clear: both; padding-top: 20px; padding-bottom: 20px;\"><p><img fetchpriority=\"high\" decoding=\"async\" class=\"alignleft wp-image-1225 size-thumbnail\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2022/07/01-300x200.jpg\" alt=\"\" width=\"300\" height=\"200\" srcset=\"https://ptakstomatologia.pl/wp-content/uploads/2022/07/01-300x200.jpg 300w, https://ptakstomatologia.pl/wp-content/uploads/2022/07/01-768x512.jpg 768w, https://ptakstomatologia.pl/wp-content/uploads/2022/07/01.jpg 1080w\" sizes=\"(max-width: 300px) 100vw, 300px\"></p><p><strong>Protezy całkowite akrylowe</strong>&nbsp;są umieszczane w jamie ustnej po usunięciu wszystkich pozostałych zębów i wygojeniu tkanek, które może trwać do 3 miesięcy. Protezy częściowe akrylowe uzupełniają częściowe braki w uzębieniu. Są one utrzymywane na zębach naturalnych za pomocą metalowych klamer (haczyków).</p><p><strong>Protezy szkieletowe</strong>&nbsp;w odróżnieniu od protez akrylowych (powyższych) mają zmniejszoną do minimum płytę akrylową, co znacznie poprawia komfort ich użytkowania. W wariantach klasycznych protezy te muszą mieć w swojej budowie klamry, ciernie itp. , które są mniej lub bardziej widoczne. W estetycznych wariantach wykonujemy protezy szkieletowe mocowane na specjalnych zasuwach, zatrzaskach co sprawia również, że proteza taka stabilnie i mocno trzyma się podłoża. Daje to użytkownikowi protezy swobodę i komfort podczas rozmowy i spożywania posiłków oraz zadowalający efekt kosmetyczny.</p></div><hr style=\"clear: both;\"><div style=\"clear: both; padding-top: 20px; padding-bottom: 20px;\"><p style=\"text-align: center;\"><strong style=\"text-align: center;\">Stałe uzupełnienia protetyczne:</strong></p><p><img decoding=\"async\" class=\"alignleft wp-image-1085 size-thumbnail\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2022/07/02.jpg\" alt=\"\" width=\"300\" height=\"200\"></p><p><strong>Korona&nbsp;</strong>– to rodzaj czapeczki, którą cementuje się na oszlifowany wcześniej ząb. Wykonujemy zarówno najpopularniejsze korony porcelanowe na podbudowie metalowej, jak i korony pełnoceramiczne.<br>Trzeba pamiętać, że koronę można założyć tylko na istniejący ząb. W przypadku, gdy zachowany został tylko korzeń (np. ząb uległ złamaniu), można zastosować specjalne wkłady koronowo – korzeniowe metalowe lub z włókna szklanego i dopiero na nie założyć koronę.</p></div><div style=\"clear: both; padding-top: 20px; padding-bottom: 20px;\"><p><img decoding=\"async\" class=\"alignleft wp-image-1226 size-thumbnail\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2022/07/03-300x200.jpg\" alt=\"\" width=\"300\" height=\"200\" srcset=\"https://ptakstomatologia.pl/wp-content/uploads/2022/07/03-300x200.jpg 300w, https://ptakstomatologia.pl/wp-content/uploads/2022/07/03-768x512.jpg 768w, https://ptakstomatologia.pl/wp-content/uploads/2022/07/03.jpg 1080w\" sizes=\"(max-width: 300px) 100vw, 300px\"><strong>Mosty&nbsp;</strong>– stosuje się je w przypadku całkowitej utraty jednego, lub kilku sąsiadujących ze sobą zębów. Most składa się z metalowego, pokrytego porcelaną „przęsła” uzupełniającego brakujące zęby oraz filarów (oszlifowane zęby własne lub wkłady koronowo -korzeniowe), na których opiera się cała konstrukcja.</p></div></div>\t\t\t\t\t\t</div>\n</div>\n<div class=\"elementor-element elementor-element-d14cdfc elementor-widget elementor-widget-heading _mPS2id-t\" data-id=\"d14cdfc\" data-element_type=\"widget\" id=\"implantologia\" data-widget_type=\"heading.default\">\n<div class=\"elementor-widget-container\">\n<h3 class=\"elementor-heading-title elementor-size-default\">Implantologia</h3>\t\t</div>\n</div>\n<div class=\"elementor-element elementor-element-59a17bc elementor-widget-divider--view-line_icon elementor-view-default elementor-widget-divider--element-align-center elementor-widget elementor-widget-divider\" data-id=\"59a17bc\" data-element_type=\"widget\" data-widget_type=\"divider.default\">\n<div class=\"elementor-widget-container\">\n<div class=\"elementor-divider\">\n<span class=\"elementor-divider-separator\">\n<div class=\"elementor-icon elementor-divider__element\">\n<i aria-hidden=\"true\" class=\"fas fa-tooth\"></i></div>\n</span>\n</div>\n</div>\n</div>\n<div class=\"elementor-element elementor-element-76b745c elementor-widget elementor-widget-text-editor\" data-id=\"76b745c\" data-element_type=\"widget\" data-widget_type=\"text-editor.default\">\n<div class=\"elementor-widget-container\">\n<p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Gabinet PTAK STOMATOLOGIA oferuje różne rodzaje uzupełnienia braków w&nbsp;uzębieniu (tzw. uzupełnień protetycznych). Są to:</b></span></span></span></p><ul><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">protezy, </span></span></span></p></li><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">korony,</span></span></span></p></li><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">mosty, </span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">a także</span></span></span></p></li><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>nowoczesne rozwiązania implantoprotetyczne. </b></span></span></span></p></li></ul><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Implanty zębowe (stomatologiczne) </b></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">są</span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"> już od dłuższego czasu </span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>popularnym i&nbsp;skutecznym sposobem na uzupełnianie braków zębowych.</b></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"> W ostatnich latach technologia w dziedzinie implantologii znacząco się rozwinęła i nadal rozwija, co pozwala na coraz bardziej&nbsp;</span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>precyzyjne i&nbsp;skuteczne leczenie</b></span></span></span> <span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>implantologiczne i&nbsp;</b></span></span></span><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>implantoprotetyczne.</b></span></span> <span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">Wszczepienie implantów to</span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b> innowacyjne rozwiązanie </b></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">w stomatologii, które</span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b> pomaga </b></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">osobom z&nbsp;utraconymi zębami </span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>odzyskać pełną funkcjonalność </b></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">swojego uzębienia. Dzięki&nbsp;implantom, </span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>pacjenci mogą cieszyć się zdrowym uśmiechem, poprawić swój wygląd oraz jakość życia. </b></span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Współczesne prace protetyczne na implantach pozwalają uzyskać doskonały efekt estetyczny</b></span></span></span> <span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>imitujący naturalny ząb.</b></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"> Leczenie stomatologiczne za pomocą implantów pozwala uniknąć kłopotów związanych z tradycyjnymi uzupełnieniami protetycznymi, np.&nbsp;wyjmowaniem protez czy szlifowaniem zdrowych zębów.</span></span></span></p><p align=\"JUSTIFY\"><img loading=\"lazy\" decoding=\"async\" class=\"aligncenter wp-image-1299\" style=\"text-align: left;\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/da.jpg\" alt=\"\" width=\"300\" height=\"200\" srcset=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/da.jpg 612w, https://ptakstomatologia.pl/wp-content/uploads/2024/11/da-300x200.jpg 300w\" sizes=\"auto, (max-width: 300px) 100vw, 300px\"></p><p align=\"JUSTIFY\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Implanty</b><span style=\"color: #000000;\"><b> to sztuczne korzenie zębów,</b></span><span style=\"color: #000000;\"> które są umieszczane w szczęce lub żuchwie pacjenta. Mają one kształt śrubki lub stożka i są wykonane z tytanu lub innych materiałów biokompatybilnych.</span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">Implanty służą do zastępowania utraconych zębów i stanowią trwałe oraz skuteczne rozwiązania dla osób, które chcą odzyskać pełną funkcjonalność swojego uzębienia. Implanty są trwale osadzone w kości, co pozwala na stabilne mocowanie korony zęba na&nbsp;implancie.</span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">Proces implantacji polega na wprowadzeniu implantu do kości, a następnie pozostawieniu go na pewien czas, aby mógł zintegrować się z kością. Po zagojeniu staje się trwałym elementem układu stomatologicznego, który umożliwia normalne funkcjonowanie zębów.</span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">Implanty są popularnym rozwiązaniem dla osób, które straciły jeden lub więcej zębów, ale&nbsp;nie chcą nosić protez ruchomych czy mostów.</span></span></span></p><p><img loading=\"lazy\" decoding=\"async\" class=\"aligncenter wp-image-1298\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/2.jpg\" alt=\"\" width=\"300\" height=\"237\"></p><p align=\"JUSTIFY\"><b> </b><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>W Gabinecie Stomatologicznym PTAK STOMATOLOGIA wykonujemy zabiegi wszczepienia implantów zębowych.</b></span></span></span> <span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">Nasi lekarze implantolodzy dysponują wiedzą i doświadczeniem w dziedzinie implantologii, stosują nowoczesne materiały i wykonują tzw. implantacje nawigowane, w tym pozycjonowanie implantów z pomocą szablonów.</span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Konsultacje implantolgiczne odbywają się poza tradycyjną listą pacjentów.</b></span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Zdjęcia poglądowe obrazujące możliwości współczesnej implantoprotetyki:</b></span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><em>(źródło: Internet, zdjęcia ogólnodostępne nieobjęte prawami autorskimi)</em></span></span></span></p><p><img loading=\"lazy\" decoding=\"async\" class=\"aligncenter wp-image-1300\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/Projekt-bez-nazwy.png\" alt=\"\" width=\"300\" height=\"128\"><img loading=\"lazy\" decoding=\"async\" class=\"aligncenter wp-image-1296\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/drugie-3.jpg\" alt=\"\" width=\"300\" height=\"106\"></p><p align=\"JUSTIFY\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><u><b>Słowniczek podstawowych pojęć:</b></u></span></span></p><p align=\"JUSTIFY\"><b>I</b><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>mplantologia </b></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">to dziedzina stomatologii, która </span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>zajmuje się wszczepianiem implantów zębowych w celu zastąpienia brakujących zębów.</b></span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Implantolog</b> to lekarz dentysta, który specjalizuje się w dziedzinie wszczepiania implantów zębowych w celu zastąpienia brakujących zębów. Implantolog <b>musi mieć odpowiednie kwalifikacje i doświadczenie</b>, aby przeprowadzać skomplikowane zabiegi implantologiczne. W tym celu <b>powinien ukończyć specjalistyczne szkolenie</b> z zakresu implantologii oraz <b>zdobyć certyfikaty potwierdzające jego kwalifikacje.</b> </span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Implant </b>(inaczej <b>wszczep śródkostny</b>) to <b>niewielka tytanowa śrubka</b>, która w trakcie zabiegu jest <b>wkręcana do kości w miejscu braku zęba.</b> Nie jest to cały odbudowany ząb, jak niektórzy sobie wyobrażają, tylko jego część, która imituje korzeń zęba. Na późniejszym etapie do śrubki przykręcany <b>jest łącznik,</b> na którym mocowana jest <b>porcelanowa korona.</b> Sam implant jest zupełnie niewidoczny i <strong>bezpieczny dla człowieka: nie wywołuje alergii ani stanów zapalnych.</strong> </span></span></span><img loading=\"lazy\" decoding=\"async\" class=\"aligncenter wp-image-1295\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/4.jpg\" alt=\"\" width=\"300\" height=\"173\"></p><p align=\"JUSTIFY\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Zabieg implantologiczny</b> jest <b>procedurą wszczepiania implantów zębowych,</b> które są metalowymi elementami, wprowadzanymi do kości szczęki lub żuchwy, w celu zastąpienia brakujących zębów. Zabieg ten <b>wymaga kilku etapów i może trwać kilka miesięcy.</b></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Leczenie implantoprotetyczne</b> to kompleksowa procedura, która polega na zastąpieniu brakujących zębów za pomocą implantów zębowych i protetyki dentystycznej. Leczenie to wymaga współpracy między implantologiem a protetykiem dentystycznym.</span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><u><b>Q&amp;A na temat implantów:</b></u></span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Jakie korzyści ma pacjent po wszczepieniu implantu w miejscu brakującego zęba/zębów?</b></span></span></span></p><ul><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>doskonałą funkcjonalność</b> takiego zęba/zębów, </span></span></span></p></li><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>komfort użytkowania,</b> </span></span></span></p></li><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>estetyczne uzupełnienie</b>, idealnie imitujące naturalnego zęba,</span></span></span></p></li><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>alternatywa dla</b><b> </b><b>protez zębowych oraz mostów,</b> które nie w każdym przypadku da się zastosować.</span></span></span></p></li><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">można wszystko jeść, mówić, poprawić wygląd twarzy, uśmiechać się w sposób nieskrepowany a tym samym cieszyć <b>lepszą jakością życia</b> i odzyskać <b>pewność siebie. </b></span></span></span></p></li></ul><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Kto podejmuje decyzję o wszczepieniu implantu?</b></span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">Decyzję podejmuje zarówno lekarz dentysta implantolog, jak i pacjent. Na wizycie konsultacyjnej lekarz dentysta implantolog zbierze od pacjenta wywiad, zbada go, zapewne zleci i oceni badanie stomatologicznej tomografii komputerowej (tzw. CBCT), a&nbsp;następnie określi jakie warunki panują w jamie ustnej pacjenta. W dalszej rozmowie omówi z pacjentem możliwości uzupełnienia luki/luk w uzębieniu. Finalnie opracuje i&nbsp;przedstawi pacjentowi do akceptacji plan leczenia oraz kosztorys.</span></span></span></p><p align=\"JUSTIFY\"><img loading=\"lazy\" decoding=\"async\" class=\"aligncenter wp-image-1312\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/6.jpg\" alt=\"\" width=\"300\" height=\"176\"></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Czy w każdym przypadku implant jest możliwy do wszczepienia?</b></span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">Niestety zdarzają się przypadki, kiedy lekarz implantolog zmuszony jest odmówić pacjentowi zabiegu wszczepienia implantu. Najczęściej wiąże się to ze złymi warunkami anatomicznymi (brak odpowiedniej grubości kości), stanem zdrowia jamy ustnej (zbyt dużo ognisk zapalnych i/lub słaba higiena jamy ustnej) stanowiącym ryzyko nie przyjęcia się implantu. Tak więc, kwalifikacja do zabiegu wszczepienia implantu/ implantów może być pozytywna lub niestety bywa i negatywna. </span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Kto wykonuje zabieg wszczepienia implantu/implantów?</b></span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">Zabieg wszczepiania implantów zębowych wykonuje lekarz dentysta implantolog. </span></span></span></p><p align=\"JUSTIFY\"><strong><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Jak wygląda proces leczenia implantorpotetycznego?</b></span></span></span></strong></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">C</span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">ały proces leczenia wymaga kilku wizyt w gabinecie stomatologicznym. Podczas zabiegu wkręcania implantu stosuje się znieczulenie miejscowe. Podczas pierwszego zabiegu lekarz implantolog wkręca/wszczepia do kości szczęki tytanową śrubkę, na której następnie przykręca łącznik, na którym na późniejszym etapie leczenia mocowana jest porcelanowa korona. W ciągu kilku miesięcy wszczepiony implant zrośnie się z kością i zastąpi naturalny korzeń zęba. Końcowy etap leczenia tzw. protetyczny, to osadzenie korony ostatecznej (właściwej). Podczas zabiegu osadzania korony, lekarz dentysta mocuje ją za pomocą łącznika lub cementu. Zabieg osadzania korony jest całkowicie bezbolesny i nie wymaga znieczulenia. </span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Na czym polega implantacja prosta?</b></span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">Implantacja prosta polega na serii wizyt zaplanowanych. Gdy kwalifikacja pacjenta do zabiegu wszczepienia implantów jest pozytywna, czynność ta odbywa się już na drugiej wizycie i odbywa w tzw. osłonie antybiotykowej. W trakcie zabiegu wszczepiania lub na kolejnym spotkaniu, do implantu przykręcany jest łącznik, na którym na dalszym etapie leczenia docelowo będzie mocowana porcelanowa korona. W dniu zabiegu wszczepiania implantu możliwa jest opcja wykonania tzw. korony tymczasowej (która zamaskuje brak zęba). W opcji drugiej implant może zostać pozostawiony bez korony tymczasowej, co ma swoje zalety: ułatwia proces gojenia i zrośnięcia się z kością. Końcowy etap leczenia tzw. protetyczny, to osadzenie korony ostatecznej (właściwej). Aby perfekcyjnie ją dopasować, lekarz dentysta pobiera klasyczny wycisk lub za pomocą skanera wewnątrzustnegio skanuje szczęki pacjenta, mierzy rozmiar, odległość między zębami oraz precyzyjnie dobiera kolor korony do sąsiadujących zębów, tak aby laboratorium protetyczne wykonało dla niego jak najlepszą koronę. Podczas zabiegu osadzania korony, lekarz dentysta mocuje ją za pomocą łącznika lub cementu. Zabieg osadzania korony jest całkowicie bezbolesny i nie wymaga znieczulenia.</span></span></span></p><p align=\"JUSTIFY\"><img loading=\"lazy\" decoding=\"async\" class=\"aligncenter wp-image-1311\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/7.jpg\" alt=\"\" width=\"300\" height=\"200\" srcset=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/7.jpg 612w, https://ptakstomatologia.pl/wp-content/uploads/2024/11/7-300x200.jpg 300w\" sizes=\"auto, (max-width: 300px) 100vw, 300px\"></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Kiedy pacjent utraci jednego zęba</b></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">, np. na skutek próchnicy, wypadku, paradontozy, nieskutecznego leczenia kanałowego lub nieskutecznej resekcji wierzchołka korzenia czy innego zdarzenia, wszczepienie implantu, jest najlepszą alternatywą dla tradycyjnego mostu. Standardowy most wymaga oszlifowania sąsiednich zębów i choć w tej technice protetycznej jest to działanie absolutnie konieczne, szlifowanie uszkadza sąsiednie zęby, a to niestety stanowi ryzyko ich obumarcia. W przypadku protez z kolei między protezę</span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"> a dziąsło dostają się resztki pokarmu, które mogą powodować stany zapalne dziąseł, uszkodzenie kości wokół zęba i cofanie dziąseł. </span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">Wszczepienie implantu pozwala uniknąć tych niepożądanych następstw.</span></span></span></p><p align=\"JUSTIFY\"><img loading=\"lazy\" decoding=\"async\" class=\"wp-image-1310 aligncenter\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/8.jpg\" alt=\"\" width=\"300\" height=\"400\"></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>W razie braku więcej niż jednego zęba</b>, potrzebna jest odbudowa kilku zębów, wówczas zamiast tradycyjnych niewygodnych czy nieestetycznych częściowych protez, które wymagają stosowania klejów i metalowych klamer, poleca się wszczepienie kilku implantów. Implanty pomagają w utrzymaniu zdrowej kości i w ten sposób na długo zachowują owal twarzy,<b> </b>zapobiegając tym samym próchnicy, stanom zapalnym i obumarciu.</span></span></span></p><p align=\"JUSTIFY\"><img loading=\"lazy\" decoding=\"async\" class=\"wp-image-1309 aligncenter\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/9.jpg\" alt=\"\" width=\"300\" height=\"225\"></p><p align=\"LEFT\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Możliwe jest wszczepienie kilku implantów</b>, w tym tworzenie dużych struktur takich jak cały łuk zębowy przytwierdzony do czterech lub sześciu implantów.</span></span></span></p><p align=\"LEFT\"><img loading=\"lazy\" decoding=\"async\" class=\"wp-image-1308 aligncenter\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/10.jpg\" alt=\"\" width=\"300\" height=\"300\"></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>W sytuacji całkowitego bezzębia</b>, tzw. protezę pełną można osadzić na ośmiu lub więcej implantach. Implanty mogą stanowić podparcie dla protezy całkowitej. Jeśli proteza będzie osadzona na implantach, nie będzie potrzeby jej częstego podścielania, polepszy się znacząco jej trwałość, a co za tym idzie komfort dla pacjenta.</span></span></span></p><p align=\"JUSTIFY\"><img loading=\"lazy\" decoding=\"async\" class=\"wp-image-1307 aligncenter\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/11.jpg\" alt=\"\" width=\"300\" height=\"225\"></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Co to jest implantacja natychmiastowa?</b></span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">Implantacja natychmiastowa jest to zabieg implantacji zaraz po zabiegu usunięcia zęba. Polega ona na usunięciu zęba i wszczepieniu implantu na jednej wizycie. Procedura ta jest możliwa tylko w przypadku, gdy warunki pozwalają na natychmiastowe umieszczenie implantu, co oznacza, że implant musi mieć odpowiednią stabilność i&nbsp;wskazania kliniczne do implantacji natychmiastowej. Zaletą implantacji natychmiastowej jest to, że pacjent ma mniej czasu na utratę kości, ponieważ implant jest umieszczany natychmiast po usunięciu zęba, co pozwala na szybszy powrót do normalnej funkcji jamy ustnej i estetyki. Jednakże, implantacja natychmiastowa jest bardziej wymagająca technicznie i może nie być odpowiednia dla każdego przypadku.</span></span></span></p><p align=\"JUSTIFY\"><img loading=\"lazy\" decoding=\"async\" class=\"wp-image-1306 aligncenter\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/12.png\" alt=\"\" width=\"300\" height=\"200\" srcset=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/12.png 626w, https://ptakstomatologia.pl/wp-content/uploads/2024/11/12-300x200.png 300w\" sizes=\"auto, (max-width: 300px) 100vw, 300px\"></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">Czasem zachodzi konieczność odbudowy kości tzw. materiałem kościozastępczym.</span></span></span></p><p align=\"JUSTIFY\"><img loading=\"lazy\" decoding=\"async\" class=\"wp-image-1305 aligncenter\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/13.jpg\" alt=\"\" width=\"300\" height=\"225\"> <img loading=\"lazy\" decoding=\"async\" class=\"wp-image-1304 aligncenter\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/14.jpg\" alt=\"\" width=\"300\" height=\"225\"></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Na czym polega pozycjonowanie implantu za pomocą szablonu?</b></span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">Pozycjonowanie implantu za pomocą szablonu to jedna z metod planowania i&nbsp;przeprowadzania implantacji stomatologicznej. Metoda ta polega na wykonaniu precyzyjnego szablonu – wydruku z drukarki 3D z wykorzystaniem specjalnej żywicy, bezpiecznej do zastosowań wewnatrzustnych, służącego do precyzyjnego umiejscowienia implantów w jamie ustnej pacjenta. Pozycjonowanie implantów za pomocą szablonu oprócz zwiększenia precyzji również ma na celu skrócenie czasu trwania zabiegu. Aby&nbsp;przeprowadzić pozycjonowanie implantu za pomocą szablonu, lekarz stomatolog wykonuje wcześniej badanie stomatologicznej tomografii komputerowej CBCT, model 3D kości szczęki i żuchwy oraz zębów pacjenta. Na&nbsp;tej podstawie zostaje zaprojektowany specjalny szablon, który będzie służył do precyzyjnego pozycjonowania implantów. Szablon jest wykonywany z tworzywa sztucznego i dopasowywany do jamy ustnej pacjenta. Posiada otwory o odpowiednich rozmiarach, które służą do umiejscowienia narzędzi stomatologicznych podczas zabiegu. W każdym otworze znajduje się także specjalne prowadzenie, które służy do pozycjonowania i stabilizacji narzędzia podczas wiercenia otworu pod implant. W trakcie zabiegu implantacji, szablon jest umieszczany na zębach pacjenta, co pozwala lekarzowi na precyzyjne wywiercenie otworów pod implanty w odpowiednich miejscach i pod odpowiednim kątem. Dzięki temu metoda ta pozwala na osiągnięcie bardzo dokładnego pozycjonowania implantów i zmniejsza ryzyko uszkodzenia struktur anatomicznych znajdujących się w pobliżu miejsca implantacji. Pozycjonowanie implantu za pomocą szablonu jest metodą bezpieczną i skuteczną, która pozwala na zminimalizowanie ryzyka powikłań i skrócenie czasu trwania zabiegu.</span></span></span></p><p align=\"JUSTIFY\"><img loading=\"lazy\" decoding=\"async\" class=\"wp-image-1303 aligncenter\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/25.jpg\" alt=\"\" width=\"300\" height=\"200\" srcset=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/25.jpg 612w, https://ptakstomatologia.pl/wp-content/uploads/2024/11/25-300x200.jpg 300w\" sizes=\"auto, (max-width: 300px) 100vw, 300px\"></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Co to jest implantacja nawigowana?</b></span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">Implantacja nawigowana to zaawansowana procedura implantologiczna, w której stosuje się systemy nawigacji komputerowej w celu precyzyjnego umieszczenia implantu w&nbsp;szczęce lub żuchwie. W przypadku implantacji nawigowanej, po wykonaniu tomografii komputerowej (CBCT) jamy ustnej i skanów 3D, tworzony jest wirtualny model jamy ustnej pacjenta, który jest przekazywany do systemu nawigacji. Następnie implantolog stosuje specjalną nakładkę nawigacyjną tzw. szablon, który pomaga w prowadzeniu wiertła podczas procedury implantologicznej, w celu osiągnięcia dokładnego i precyzyjnego umieszczenia implantu w zębodole. Implantacja nawigowana zapewnia wysoką precyzję i&nbsp;minimalnie inwazyjny charakter zabiegu, co przekłada się na mniejsze ryzyko powikłań i&nbsp;krótszy czas gojenia się pacjenta. System nawigacji komputerowej umożliwia również lepszą ocenę ilości i jakości kości, co może pomóc w dokładniejszym planowaniu procedury. </span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Od czego zależy trwałość leczenia implantoprotetycznego?</b></span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">W idealnych warunkach, implanty stomatologiczne mogą służyć na całe życie. Jednak, trwałość implantów stomatologicznych zależy od wielu czynników, takich jak:</span></span></span></p><ul><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Stanu zdrowia pacjenta: </b></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">pacjenci z dobrym stanem zdrowia ogólnego mają zwykle lepsze wyniki po zabiegu implantoprotetycznym. </span></span></span></p></li><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Właściwego dobrania implantów:</b></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"> wybór odpowiedniego rodzaju i wielkości implantów oraz właściwe ich umiejscowienie są kluczowe dla uzyskania trwałego leczenia implantoprotetycznego. </span></span></span></p></li><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Doświadczenia i umiejętności lekarza implantologa:</b></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"> jakość wykonania zabiegu implantoprotetycznego jest ważna dla długotrwałego efektu. </span></span></span></p></li><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Rzetelności i umiejętności protetyka:</b></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"> dobór odpowiednich materiałów i technik protetycznych ma kluczowe znaczenie dla uzyskania trwałego leczenia implantoprotetycznego. </span></span></span></p></li><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Starannego przestrzegania zaleceń pooperacyjnych:</b></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"> pacjenci muszą przestrzegać zaleceń pooperacyjnych, aby uniknąć infekcji i zapewnić odpowiednie warunki dla implantów do integracji z kością. </span></span></span></p></li><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Stylu życia pacjenta:</b></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"> styl życia, dieta i nawyki higieniczne pacjenta mogą wpłynąć na trwałość leczenia implantoprotetycznego. </span></span></span></p></li></ul><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">Jeśli pacjent przestrzega zasad higieny jamy ustnej i regularnie odwiedza stomatologa, to&nbsp;implanty stomatologiczne mogą służyć przez długi czas. W przypadku jakichkolwiek problemów, takich jak infekcja lub uszkodzenie implantu, należy niezwłocznie skonsultować się z lekarzem implantologiem, aby uniknąć poważniejszych komplikacji i&nbsp;konieczności usunięcia implantu.</span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">Należy pamiętać, że każdy pacjent jest inny i każdy przypadek implantoprotetyczny jest unikalny, dlatego trwałość implantów może być różna u różnych pacjentów.</span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Jak się przygotować do zabiegu implantacji stomatologicznej?</b></span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">Przygotowanie do zabiegu implantacji stomatologicznej jest bardzo ważne, aby zapewnić sukces zabiegu i skrócić czas rekonwalescencji. Oto kilka zaleceń dotyczących przygotowań przed zabiegiem implantacji:</span></span></span></p><ul><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Skonsultuj się z lekarzem:</b> Przed zabiegiem implantacji należy skonsultować się z&nbsp;implantologiem, który przeprowadzi badanie i oceni stan jamy ustnej. Lekarz może przepisać dodatkowe badania, takie jak zdjęcie panoramiczne lu CBCT, aby ocenić strukturę kości i wybrać odpowiednie implanty.</span></span></span></p></li><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Przestrzegaj zaleceń: </b>Przestrzegaj zaleceń lekarza przed zabiegiem, takich jak przerwanie przyjmowania leków przeciwzakrzepowych lub innych leków, które mogą wpływać na krzepliwość krwi, lub wykonywanie badań laboratoryjnych.</span></span></span></p></li><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Unikaj palenia i picia alkoholu:</b> Palenie i picie alkoholu przed zabiegiem implantacji mogą opóźnić proces gojenia i zwiększyć ryzyko powikłań. </span></span></span></p></li><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Zaplanuj czas rekonwalescencji:</b> Po zabiegu implantacji konieczne może być kilka dni lub nawet tygodni rekonwalescencji. Zaplanuj swój czas w ten sposób, aby móc odpocząć i unikać sytuacji, które mo</span></span></span></p><p><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">gą prowadzić do infekcji lub uszkodzenia implantów. </span></span></span></p></li><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Przygotuj odpowiednią dietę: </b>Po zabiegu implantacji pacjent może odczuwać dyskomfort i ból. W związku z tym zaleca się spożywanie miękkich i łatwo strawnych pokarmów, takich jak zupy, puree ziemniaczane, gotowane warzywa, jogurty i smoothie.</span></span></span></p></li><li><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Dbaj o higienę jamy ustnej: </b>Przed i po zabiegu implantacji należy dbać o higienę jamy ustnej, szczególnie w miejscu, gdzie zostaną umieszczone implanty. Wskazane jest dokładne szczotkowanie zębów, stosowanie nici dentystycznej oraz płukanie jamy ustnej specjalnymi roztworami przepisanymi przez lekarza.</span></span></span></p></li></ul><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">Przygotowanie się do zabiegu implantacji wymaga dokładnego planowania i&nbsp;przestrzegania zaleceń lekarza. W ten sposób można zmniejszyć ryzyko powikłań i&nbsp;zwiększyć szanse na sukces zabiegu.</span></span></span></p><p align=\"JUSTIFY\"><img loading=\"lazy\" decoding=\"async\" class=\"wp-image-1302 aligncenter\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/16-768x512.jpg\" alt=\"\" width=\"300\" height=\"200\" srcset=\"https://ptakstomatologia.pl/wp-content/uploads/2024/11/16-768x512.jpg 768w, https://ptakstomatologia.pl/wp-content/uploads/2024/11/16-1620x1080.jpg 1620w, https://ptakstomatologia.pl/wp-content/uploads/2024/11/16-300x200.jpg 300w, https://ptakstomatologia.pl/wp-content/uploads/2024/11/16-1536x1024.jpg 1536w, https://ptakstomatologia.pl/wp-content/uploads/2024/11/16-2048x1365.jpg 2048w\" sizes=\"auto, (max-width: 300px) 100vw, 300px\"></p>\t\t\t\t\t\t</div>\n</div>\n<div class=\"elementor-element elementor-element-7e37c35 elementor-widget elementor-widget-heading _mPS2id-t\" data-id=\"7e37c35\" data-element_type=\"widget\" id=\"ortodoncja\" data-widget_type=\"heading.default\">\n<div class=\"elementor-widget-container\">\n<h3 class=\"elementor-heading-title elementor-size-default\">Ortodoncja</h3>\t\t</div>\n</div>\n<div class=\"elementor-element elementor-element-f6bda35 elementor-widget-divider--view-line_icon elementor-view-default elementor-widget-divider--element-align-center elementor-widget elementor-widget-divider\" data-id=\"f6bda35\" data-element_type=\"widget\" data-widget_type=\"divider.default\">\n<div class=\"elementor-widget-container\">\n<div class=\"elementor-divider\">\n<span class=\"elementor-divider-separator\">\n<div class=\"elementor-icon elementor-divider__element\">\n<i aria-hidden=\"true\" class=\"fas fa-tooth\"></i></div>\n</span>\n</div>\n</div>\n</div>\n<div class=\"elementor-element elementor-element-39be806 elementor-widget elementor-widget-text-editor\" data-id=\"39be806\" data-element_type=\"widget\" data-widget_type=\"text-editor.default\">\n<div class=\"elementor-widget-container\">\n<p><b>Ortodoncja – Specjalizacja w leczeniu wad zgryzu i nieprawidłowości zębów</b></p><p>Ortodoncja to gałąź stomatologii, która specjalizuje się w diagnozowaniu, leczeniu i zapobieganiu wadom zgryzu oraz nieprawidłowościom w ustawieniu zębów i szczęk. Celem leczenia ortodontycznego jest poprawa funkcji zgryzu, estetyki twarzy oraz komfortu pacjenta.</p><p>Nieprawidłowy zgryz może wynikać z różnych przyczyn, takich jak genetyka, wczesna utrata zębów mlecznych, nieprawidłowe nawyki (np. ssanie kciuka), urazy czy wady wrodzone. Wady zgryzu mogą prowadzić do problemów z gryzieniem, żuciem, mówieniem, a także powodować ból stawów skroniowo-żuchwowych (TMJ) oraz nadmierne zużycie zębów.</p><p>Leczenie ortodontyczne opiera się na zastosowaniu aparatów ortodontycznych, które stopniowo przesuwają zęby do prawidłowej pozycji. W zależności od wieku pacjenta, rodzaju wady i jej nasilenia, stosuje się różne rodzaje aparatów – od tradycyjnych metalowych, przez aparaty ceramiczne, aż po niewidoczne aparaty lingwalne czy nakładki Invisalign.</p><p>Ortodoncja nie tylko poprawia estetykę uśmiechu, ale także wpływa na zdrowie jamy ustnej, poprawiając funkcję żucia i zapobiegając problemom związanym z nadmiernym ścieraniem zębów czy bólem stawów skroniowo-żuchwowych.</p><p>Leczenie ortodontyczne jest skuteczne w każdym wieku, choć najczęściej podejmowane jest w okresie dorastania, kiedy kości i zęby są najbardziej podatne na korektę. Jednak coraz więcej dorosłych pacjentów decyduje się na leczenie ortodontyczne w celu poprawy funkcji zgryzu i estetyki.</p><p><img loading=\"lazy\" decoding=\"async\" class=\"alignnone wp-image-1320\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort1-768x384.jpg\" alt=\"\" width=\"387\" height=\"194\" srcset=\"https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort1-768x384.jpg 768w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort1-1536x769.jpg 1536w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort1.jpg 1768w\" sizes=\"auto, (max-width: 387px) 100vw, 387px\"></p><p>Przed</p><p><img loading=\"lazy\" decoding=\"async\" class=\"alignnone wp-image-1321\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort2-768x512.jpg\" alt=\"\" width=\"388\" height=\"259\" srcset=\"https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort2-768x512.jpg 768w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort2-1620x1080.jpg 1620w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort2-300x200.jpg 300w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort2-1536x1024.jpg 1536w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort2-2048x1365.jpg 2048w\" sizes=\"auto, (max-width: 388px) 100vw, 388px\"> &nbsp;&nbsp;&nbsp;</p><p><span style=\"font-weight: 400;\">Po 2 wizytach kontrolnych</span></p><p><span style=\"font-weight: 400;\">DLACZEGO WAŻNE JEST WCZESNE LECZENIE ORTODONTYCZNE?</span></p><p><b>Wczesne leczenie ortodontyczne</b><span style=\"font-weight: 400;\"> jest kluczowe z kilku powodów, które mają wpływ na zdrowie jamy ustnej, rozwój zgryzu i estetykę twarzy. Oto najważniejsze z nich:</span></p><h6><span style=\"color: #0a2f40;\"><b>1. Wczesna diagnoza wad zgryzu</b></span></h6><p><span style=\"font-weight: 400;\">Niektóre wady zgryzu, takie jak <span style=\"color: #162736;\">zgryz</span> otwarty, krzyżowy czy głęboki, mogą być trudne do wykrycia u dzieci bez odpowiedniej diagnostyki. Wczesna konsultacja z ortodontą pozwala na identyfikację problemów, które mogą nie być widoczne gołym okiem. Dzięki temu możliwe jest wczesne rozpoczęcie leczenia, co zapobiega pogłębianiu się problemów w późniejszych latach.</span></p><h6><span style=\"color: #0a2f40;\"><b>2. Optymalizacja wzrostu i rozwoju szczęki</b></span></h6><p><span style=\"font-weight: 400;\">W okresie wczesnego rozwoju (około 6-10 roku życia) kości szczęki i żuchwy są bardziej elastyczne, co ułatwia ich korygowanie. Leczenie ortodontyczne w tym wieku, zwłaszcza w przypadku wad związanych z rozwojem szczęki, może pomóc w prawidłowym wzroście kości twarzy, zmniejszając konieczność bardziej inwazyjnych zabiegów w przyszłości.</span></p><h6><span style=\"color: #0a2f40;\"><b>3. Poprawa funkcji zgryzu i mowy</b></span></h6><p><span style=\"font-weight: 400;\">Wczesne leczenie może zapobiec problemom z gryzieniem, żuciem, a także mówieniem. Nieprawidłowy zgryz może wpływać na sposób, w jaki dziecko gryzie pokarm, co prowadzi do nieprawidłowego rozwoju mięśni twarzy, a także może powodować trudności w artykulacji. Korygowanie zgryzu na wczesnym etapie umożliwia uniknięcie takich problemów.</span></p><h6><span style=\"color: #0a2f40;\"><b>4. Prewencja problemów zdrowotnych</b></span></h6><p><span style=\"font-weight: 400;\">Wczesne leczenie ortodontyczne może zapobiegać dalszym problemom zdrowotnym, takim jak nadmierne ścieranie zębów, ból stawów skroniowo-żuchwowych (TMJ) czy zmiany w postawie ciała spowodowane niewłaściwym ustawieniem szczęki. Może również pomóc w zapobieganiu próchnicy i chorobom dziąseł, które mogą wystąpić w wyniku trudności w utrzymaniu prawidłowej higieny jamy ustnej przy źle ustawionych zębach.</span></p><h6><span style=\"color: #0a2f40;\"><b>5. Zwiększenie komfortu pacjenta</b></span></h6><p><span style=\"font-weight: 400;\">Leczenie w młodym wieku może sprawić, że dziecko szybciej przyzwyczai się do noszenia aparatu ortodontycznego i zyska większy komfort w porównaniu do leczenia w późniejszych latach, kiedy zmiany w strukturze twarzy i zębów mogą być bardziej zaawansowane.</span></p><h6><span style=\"color: #0a2f40;\"><b>6. Poprawa estetyki twarzy i pewności siebie</b></span></h6><p><span style=\"font-weight: 400;\">Kiedy zęby są nierówno ustawione, może to wpływać na wygląd twarzy dziecka i jego pewność siebie. Wczesne leczenie ortodontyczne nie tylko poprawia funkcję zgryzu, ale także estetykę uśmiechu, co ma duże znaczenie w okresie dorastania, kiedy dzieci i nastolatki szczególnie dbają o swój wygląd.</span></p><h6><span style=\"color: #0a2f40;\"><b>7. Mniejsze koszty leczenia w przyszłości</b></span></h6><p><span style=\"font-weight: 400;\">Dzięki wczesnemu leczeniu ortodontycznemu często możliwe jest zapobieganie poważniejszym wadom, które mogłyby wymagać bardziej skomplikowanego i kosztownego leczenia w przyszłości. Wczesna interwencja może zatem zredukować koszty i czas leczenia w dorosłym życiu.</span></p><p>&nbsp;</p><h6><span style=\"color: #0a2f40;\"><b>Kiedy warto rozpocząć leczenie ortodontyczne?</b></span></h6><p><span style=\"font-weight: 400;\">Według rekomendacji Amerykańskiej Akademii Ortodoncji, pierwsza wizyta u ortodonty powinna odbyć się około 7. roku życia. W tym wieku ortodonta może ocenić rozwój zgryzu i zalecić odpowiednie leczenie, jeśli jest ono konieczne.</span></p><p><span style=\"font-weight: 400;\">Podsumowując, </span><b>wczesne leczenie ortodontyczne</b><span style=\"font-weight: 400;\"> pozwala na szybsze i mniej skomplikowane korekty, które w przyszłości mogą przynieść lepsze efekty zarówno zdrowotne, jak i estetyczne.</span></p><p><img loading=\"lazy\" decoding=\"async\" class=\"alignnone wp-image-1322\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort3-768x512.jpg\" alt=\"\" width=\"390\" height=\"260\" srcset=\"https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort3-768x512.jpg 768w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort3-1620x1080.jpg 1620w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort3-300x200.jpg 300w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort3-1536x1024.jpg 1536w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort3-2048x1365.jpg 2048w\" sizes=\"auto, (max-width: 390px) 100vw, 390px\"></p><p><span style=\"font-weight: 400;\">W celu wykonania aparatu u dzieci pobierany jest </span><b>skan,</b><span style=\"font-weight: 400;\"> dzięki czemu możemy uniknąć niezbyt przyjemnych wycisków zębów.</span></p><p><span style=\"font-weight: 400;\">Na podstawie wydrukowanego modelu 3D wykonywany jest aparat.</span></p><p><span style=\"font-weight: 400;\">Montaż aparatu w jamie ustnej jest </span><b>bezbolesny</b><span style=\"font-weight: 400;\">. Każdy najmłodszy pacjent ma możliwość wyboru </span><b>koloru aparatu</b><span style=\"font-weight: 400;\">.</span></p><p><img loading=\"lazy\" decoding=\"async\" class=\"alignnone wp-image-1323\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort4-768x509.jpg\" alt=\"\" width=\"384\" height=\"254\" srcset=\"https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort4-768x509.jpg 768w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort4-1628x1080.jpg 1628w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort4-1536x1019.jpg 1536w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort4-2048x1358.jpg 2048w\" sizes=\"auto, (max-width: 384px) 100vw, 384px\"></p><p><b>W leczeniu młodzieży i dorosłych stosujemy zamki Pitts 21 Pro</b><span style=\"font-weight: 400;\"> to nowoczesne zamki ortodontyczne, które są częścią systemu ortodontycznego opracowanego przez dr. Richarda Pitta, który stworzył system Pitts 21. Charakteryzują się one innowacyjnymi cechami, które pomagają w bardziej efektywnym leczeniu ortodontycznym, zapewniając lepsze kontrolowanie ruchu zębów oraz skrócenie czasu leczenia. Poniżej przedstawiam kluczowe cechy zamków </span><b>Pitts 21 Pro</b><span style=\"font-weight: 400;\">:</span></p><h6><span style=\"color: #0a2f40;\"><b>1. Zaawansowana technologia</b></span></h6><p><span style=\"font-weight: 400;\">Zamki Pitts 21 Pro są zaprojektowane z myślą o maksymalnej precyzji leczenia.&nbsp;</span></p><h6><span style=\"color: #0a2f40;\"><b>2. Zwiększona kontrola nad ruchem zębów</b></span></h6><p><span style=\"font-weight: 400;\">Dzięki nowoczesnej konstrukcji i zastosowaniu zaawansowanego materiału, zamki Pitts 21 Pro oferują </span><b>lepszą kontrolę nad ruchem zębów</b><span style=\"font-weight: 400;\">, zarówno w płaszczyźnie poziomej, jak i pionowej. Ułatwia to precyzyjne dostosowywanie ustawienia zębów, co może przyspieszyć cały proces leczenia i poprawić jego efektywność.</span></p><h6><span style=\"color: #0a2f40;\"><b>3. Mniejsze ryzyko uszkodzenia aparatu</b></span></h6><p><span style=\"font-weight: 400;\">Zamki Pitts 21 Pro charakteryzują się </span><b>większą trwałością</b><span style=\"font-weight: 400;\"> i odpornością na uszkodzenia mechaniczne, co sprawia, że aparat jest bardziej odporny na zniszczenie w trakcie leczenia.</span></p><h6><span style=\"color: #0a2f40;\"><b>4. Zwiększona estetyka i komfort</b></span></h6><p><span style=\"font-weight: 400;\">W systemie Pitts 21 Pro zastosowano zamki, które są </span><b>mniejsze i bardziej estetyczne</b><span style=\"font-weight: 400;\">, co pozwala na bardziej dyskretne leczenie. W porównaniu do tradycyjnych aparatów, zamki te powodują mniejszy dyskomfort podczas codziennego użytkowania.</span></p><h6><span style=\"color: #0a2f40;\"><b>5. Optymalizacja procesu leczenia</b></span></h6><p><span style=\"font-weight: 400;\">Pitts 21 Pro oferuje </span><b>szybsze osiąganie wyników</b><span style=\"font-weight: 400;\"> w porównaniu do starszych systemów ortodontycznych. Dzięki precyzyjnemu projektowi zamków oraz odpowiedniej technologii łuków, leczenie może być zakończone w krótszym czasie, a pacjent doświadcza mniejszego dyskomfortu.</span></p><h6><span style=\"color: #0a2f40;\"><b>6. Leczenie przy minimalnych interwencjach</b></span></h6><p><span style=\"font-weight: 400;\">Zamki Pitts 21 Pro pozwalają na uzyskanie pożądanych rezultatów z </span><b>minimalną liczbą wizyt kontrolnych</b><span style=\"font-weight: 400;\"> i interwencji ortodonty, co wpływa na komfort pacjenta oraz oszczędność czasu.</span></p><h6><span style=\"color: #0a2f40;\"><b>Podsumowanie</b></span></h6><p><b>Zamki Pitts 21 Pro</b><span style=\"font-weight: 400;\"> to nowoczesne rozwiązanie w leczeniu ortodontycznym, które oferuje wiele korzyści w zakresie estetyki, komfortu, efektywności i szybkości leczenia. Dzięki zaawansowanej technologii i precyzyjnej konstrukcji, system Pitts 21 Pro umożliwia uzyskanie doskonałych wyników w krótszym czasie, jednocześnie zmniejszając ryzyko powikłań i zapewniając pacjentowi większą satysfakcję z leczenia.</span></p><p><img loading=\"lazy\" decoding=\"async\" class=\"wp-image-1324 alignleft\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort5-540x720.jpg\" alt=\"\" width=\"251\" height=\"335\" srcset=\"https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort5-540x720.jpg 540w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort5-810x1080.jpg 810w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort5-768x1024.jpg 768w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort5-1152x1536.jpg 1152w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort5.jpg 1536w\" sizes=\"auto, (max-width: 251px) 100vw, 251px\"><img loading=\"lazy\" decoding=\"async\" class=\"alignnone  wp-image-1325\" src=\"https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort6-540x720.jpg\" alt=\"\" width=\"257\" height=\"342\" srcset=\"https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort6-540x720.jpg 540w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort6-810x1080.jpg 810w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort6-768x1024.jpg 768w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort6-1152x1536.jpg 1152w, https://ptakstomatologia.pl/wp-content/uploads/2025/02/ort6.jpg 1536w\" sizes=\"auto, (max-width: 257px) 100vw, 257px\"></p>\t\t\t\t\t\t</div>\n</div>\n<div class=\"elementor-element elementor-element-0b3418f elementor-widget elementor-widget-heading\" data-id=\"0b3418f\" data-element_type=\"widget\" data-widget_type=\"heading.default\">\n<div class=\"elementor-widget-container\">\n<h3 class=\"elementor-heading-title elementor-size-default\">Stomatologia estetyczna</h3>\t\t</div>\n</div>\n<div class=\"elementor-element elementor-element-82448ba elementor-widget-divider--view-line_icon elementor-view-default elementor-widget-divider--element-align-center elementor-widget elementor-widget-divider\" data-id=\"82448ba\" data-element_type=\"widget\" data-widget_type=\"divider.default\">\n<div class=\"elementor-widget-container\">\n<div class=\"elementor-divider\">\n<span class=\"elementor-divider-separator\">\n<div class=\"elementor-icon elementor-divider__element\">\n<i aria-hidden=\"true\" class=\"fas fa-tooth\"></i></div>\n</span>\n</div>\n</div>\n</div>\n<div class=\"elementor-element elementor-element-bf71f65 elementor-widget elementor-widget-text-editor\" data-id=\"bf71f65\" data-element_type=\"widget\" data-widget_type=\"text-editor.default\">\n<div class=\"elementor-widget-container\">\n<p>W związku z wzrastającym zapotrzebowaniem pacjentów na zdrowy i piękny uśmiech proponujemy Państwu szereg nowoczesnych rozwiązań, dostosowanych do Państwa indywidualnych potrzeb i oczekiwań.<br>Znajdują się wśród nich:</p><ul><li>Wybielanie,</li><li>estetyczne wypełnienie kompozytowe,</li><li>rozwiązania protetyczne (tj. korony, mosty w tym całoceramiczne).</li></ul>\t\t\t\t\t\t</div>\n</div>\n<div class=\"elementor-element elementor-element-241970a elementor-widget elementor-widget-heading _mPS2id-t\" data-id=\"241970a\" data-element_type=\"widget\" id=\"higienizacja\" data-widget_type=\"heading.default\">\n<div class=\"elementor-widget-container\">\n<h3 class=\"elementor-heading-title elementor-size-default\">Higienizacja</h3>\t\t</div>\n</div>\n<div class=\"elementor-element elementor-element-8bcf104 elementor-widget-divider--view-line_icon elementor-view-default elementor-widget-divider--element-align-center elementor-widget elementor-widget-divider\" data-id=\"8bcf104\" data-element_type=\"widget\" data-widget_type=\"divider.default\">\n<div class=\"elementor-widget-container\">\n<div class=\"elementor-divider\">\n<span class=\"elementor-divider-separator\">\n<div class=\"elementor-icon elementor-divider__element\">\n<i aria-hidden=\"true\" class=\"fas fa-tooth\"></i></div>\n</span>\n</div>\n</div>\n</div>\n<div class=\"elementor-element elementor-element-4ad8c0e elementor-widget elementor-widget-text-editor\" data-id=\"4ad8c0e\" data-element_type=\"widget\" data-widget_type=\"text-editor.default\">\n<div class=\"elementor-widget-container\">\n<p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\"><b>Co to jest higienizacja?</b></span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif; font-size: 1rem;\">Higienizacja to </span><b style=\"font-family: Arial, sans-serif; font-size: 1rem;\">następujące po sobie trzy zabie</b><strong>g</strong><span style=\"font-family: Arial, sans-serif; font-size: 1rem;\"><strong>i profilaktyczne</strong>, takie jak:</span></p><ul><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">usuwanie kamienia, tzw. skaling, </span></p></li><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">piaskowanie,</span></p></li><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">fluoryzacja profesjonalna.</span></p></li></ul><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\"><b>&nbsp;</b></span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\"><b>Kto wykonuje higienizację?</b></span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">Zabiegi higienizacyjne wykonuje l<b>ekarz stomatolog </b>albo <b>profesjonalna higienistka stomatologiczna.</b></span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\"><b>&nbsp;</b></span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\"><b>Co to jest skaling?</b></span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">Skaling o </span><span style=\"font-family: Arial, sans-serif;\"><b>zabieg usuwania kamienia </b></span><span style=\"font-family: Arial, sans-serif;\">nazębnego,</span><span style=\"font-family: Arial, sans-serif;\"> naddziąsłowego i poddziąsłowego </span><span style=\"font-family: Arial, sans-serif;\"><b>z&nbsp;użyciem</b></span> <span style=\"font-family: Arial, sans-serif;\"><b>ultradźwięków</b></span><span style=\"font-family: Arial, sans-serif;\"> emitowanych z urządzenia zwanego skalerem. Ultradźwięki są nie odczuwalne i nie powodują uszkodzenia szkliwa. </span><span style=\"font-family: Arial, sans-serif;\">Każdy skaling kończony jest polerowaniem wszystkich czyszczonych powierzchni. Zapewnia to przyjemne uczucie gładkości zębów i zapobiega ponownemu odkładaniu się płytki nazębnej.</span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\"><b>&nbsp;</b></span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\"><b>Co to jest kamień? </b></span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">Kamień to</span><span style=\"font-family: Arial, sans-serif;\"><b> złogi nazębne</b></span><span style=\"font-family: Arial, sans-serif;\">, które powstają </span><span style=\"font-family: Arial, sans-serif;\"><b>ze związków mineralnych zawartych w ślinie. </b></span></p><ul><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">Kamień zawiera liczne bakterie odpowiedzialne między innymi za przykry zapach z&nbsp;ust, przebarwienia, paradontozę, pośrednio również za próchnicę. </span></p></li><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">Zła higiena znacznie przyspiesza odkładanie się kamienia. </span></p></li><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">In</span><span style=\"font-family: Arial, sans-serif;\">tensywność tworzenia się kamienia jest różna u poszczególnych osób. </span></p></li></ul><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\"><b>&nbsp;</b></span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\"><b>Dlaczego warto usuwać kamień?</b></span></p><ul><li><p align=\"LEFT\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">usuwanie kamienia </span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>likwiduje</b></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"> widoczne </span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>przebarwienia</b></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"> zębów </span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">(walory estetyczne)</span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"> i często </span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>nieprzyjemny zapach z ust,</b></span></span></span></p></li><li><p align=\"LEFT\"><span style=\"color: #000000;\"><span style=\"font-family: Roboto, sans-serif;\"><span style=\"font-size: medium;\"><b>zapobiega powstawaniu stanów zapalnych dziąseł i przyzębia,</b></span></span></span></p></li><li><p align=\"LEFT\"><span style=\"color: #000000;\"><span style=\"font-family: Roboto, sans-serif;\"><span style=\"font-size: medium;\"><b>zmniejsza ryzyko</b></span></span></span> <span style=\"color: #000000;\"><span style=\"font-family: Roboto, sans-serif;\"><span style=\"font-size: medium;\"><b>chorób takich jak</b></span></span></span> <span style=\"color: #000000;\"><span style=\"font-family: Roboto, sans-serif;\"><span style=\"font-size: medium;\"><b>próchnica czy paradontoza.</b></span></span></span></p></li></ul><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\"><b>&nbsp;</b></span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\"><b>Dlaczego warto usuwać kamień regularnie?</b></span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">Regularne usuwanie <b>pozwala zapobiec wyżej wymienionym problemom.</b></span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\"><b>&nbsp;</b></span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\"><b>Co to jest piaskowanie?</b></span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">Piaskowanie to </span><span style=\"font-family: Arial, sans-serif;\"><b>usuwanie miękkiego osadu i przebarwień powstałych od kawy, herbaty, palenia papierosów. </b></span><span style=\"font-family: Arial, sans-serif;\">Piaskowanie odbywa się z użyciem aparatu, które pod dużym ciśnieniem, cienkim strumieniem „wyrzuca” mieszankę wody i powietrza z drobinkami węglowodanu sodu (substancja czyszcząca). </span><span style=\"color: #000000;\"><span style=\"font-family: Open Sans, sans-serif;\"><span style=\"font-size: medium;\">Dodane do wody granulki nazywane są piaskiem stomatologicznym, stąd pochodzi nazwa zabiegu.</span></span></span></p><ul><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">Piaskowanie jest uzupełnieniem skalingu, gdyż bardzo dobrze czyści przestrzenie międzyzębowe, daje uczucie odświeżonych zębów. </span></p></li><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">Częstotliwość konieczności piaskowania wynika z indywidualnych potrzeb pacjenta.</span></p></li><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">Piaskowanie, podobnie jak skaling, to zabieg całkowicie bezbolesny i&nbsp;bezpieczny. </span></p></li></ul><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\"><b>&nbsp;</b></span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\"><b>Co to jest fluoryzacja profesjonalna?</b></span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">Fluoryzacja profesjonalna, inaczej profilaktyka fluorkowa czy po prostu fluoryzacja to </span><span style=\"font-family: Arial, sans-serif;\"><b>powlekanie zębów</b></span> <span style=\"font-family: Arial, sans-serif;\"><b>warstwą preparatu</b></span><span style=\"font-family: Arial, sans-serif;\"> o wysokiej zawartości</span><span style=\"font-family: Arial, sans-serif;\"><b> fluoru: lakierem (nazwa tej usługi to lakierowanie), żelem lub pianką.&nbsp;</b></span></p><ul><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">Zabieg fluoryzacji może być wykonywany zarówno u dzieci (zęby mleczne i stałe), jak i u dorosłych.</span></p></li><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">Fluoryzacja</span> <span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">przyniesie największe efekty, jeśli wykona się ją po </span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">skalingu</span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">&nbsp;</span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">i&nbsp;</span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">piaskowaniu, ponieważ osad czy kamień nazębny utrudnią dostarczanie zębom fluoru. </span></span></span></p></li><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">Częstotliwość fluoryzacji zależy od indywidualnych skłonności do próchnicy. Rutynowo fluoryzację zębów powinno się przeprowadzić dwa razy do roku, po każdorazowym zabiegu usuwania kamienia nazębnego i piaskowaniu. </span></p></li></ul><p align=\"LEFT\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>&nbsp;</b></span></span></span></p><p align=\"LEFT\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>W jakim celu stosuje się fluoryzację?</b></span></span></span></p><p align=\"LEFT\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\">Fluoryzację wykonuje się w celu zapobiegania próchnicy oraz nadwrażliwości zębów. </span></span></span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\"><b>&nbsp;</b></span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\"><b>Jakie są inne działania profilaktyczne? </b></span></p><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">Są to:</span></p><ul><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">przegląd stomatologiczny,</span></p></li><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">edukacja zdrowotna,</span></p></li><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">wdrażanie właściwych nawyków higienicznych i żywieniowych, </span></p></li><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">dobry przykład.</span></p></li></ul><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>&nbsp;</b></span></span></span></p><p align=\"JUSTIFY\"><span style=\"color: #000000;\"><span style=\"font-family: Arial, sans-serif;\"><span style=\"font-size: medium;\"><b>Przegląd stomatologiczny:</b></span></span></span></p><ul><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">Powinien być wykonywany przynajmniej raz w roku. </span></p></li><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">Umożliwia zdiagnozowanie patologicznych zmian w obrębie uzębienia, dziąseł i&nbsp;błony śluzowej oraz ocenę higieny jamy ustnej. </span></p></li><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">Pozwala na indywidualny dobór techniki oczyszczania zębów, pasty i szczoteczki a także instruktaż.</span></p></li><li><p align=\"LEFT\"><span style=\"font-family: Arial, sans-serif;\">Wykonuje go lekarz stomatolog.</span></p></li></ul>\t\t\t\t\t\t</div>\n</div>\n<div class=\"elementor-element elementor-element-a8be197 elementor-widget elementor-widget-heading _mPS2id-t\" data-id=\"a8be197\" data-element_type=\"widget\" id=\"nowoczesne-technologie\" data-widget_type=\"heading.default\">\n<div class=\"elementor-widget-container\">\n<h3 class=\"elementor-heading-title elementor-size-default\">Nowoczesne technologie</h3>\t\t</div>\n</div>\n<div class=\"elementor-element elementor-element-231a5f9 elementor-widget-divider--view-line_icon elementor-view-default elementor-widget-divider--element-align-center elementor-widget elementor-widget-divider\" data-id=\"231a5f9\" data-element_type=\"widget\" data-widget_type=\"divider.default\">\n<div class=\"elementor-widget-container\">\n<div class=\"elementor-divider\">\n<span class=\"elementor-divider-separator\">\n<div class=\"elementor-icon elementor-divider__element\">\n<i aria-hidden=\"true\" class=\"fas fa-tooth\"></i></div>\n</span>\n</div>\n</div>\n</div>\n<div class=\"elementor-element elementor-element-a47333d elementor-widget elementor-widget-text-editor\" data-id=\"a47333d\" data-element_type=\"widget\" data-widget_type=\"text-editor.default\">\n<div class=\"elementor-widget-container\">\n<p>Nowoczesne urządzenia umożliwiają wykonywanie takich zabiegów, jakich pacjenci potrzebują najbardziej: bezbolesnych, szybkich i o spektakularnych efektach.</p><p><strong>Tomografia komputerowa</strong></p><p><strong>Aparat rentgenowski</strong></p><p>Aparat rentgenowski służy do wykonywania punktowych zdjęć wewnątrz ustnych:</p><ul><li>zdjęć pojedynczych zębów,</li><li>zdjęć zgryzowych,</li><li>zdjęć zgryzowo – skrzydłowych.</li></ul><p><strong>Radiografia cyfrowa</strong></p><p>Umożliwia wykonanie zdjęcia na fotelu stomatologicznym, bez konieczności wywołania kliszy. Obraz transmitowany jest na ekran monitora zaledwie w kilka sekund. Pozwala zmniejszyć dawki promieniowania . Szybka i bezpieczna metoda diagnostyki.</p><p><strong>Znieczulenie komputerowe</strong></p><p>Znieczulenie komputerowe SleeperOne – to urządzenie umożliwiające podawanie środka znieczulającego kontrolowane przez mikroprocesor. System ten analizuje opór tkanek i dostosowuje ciśnienie tak ,aby nie przekroczyło granicy odczuwania bólu. Dzięki temu proces znieczulania jest krótki i bezbolesny, a przyjazny wygląd przypominający długopis pozwala wyeliminować strach przed igłą.</p><p><strong>SuperEndo Beta &amp; Alfa</strong></p><p>B&amp;L SuperEndo Beta to innowacyjne, kompaktowe i bezprzewodowe urządzenie do optymalnego wypełniania kanałów podczas leczenia endodontycznego. Gwarantuje precyzyjne i trójwymiarowe wypełnienie kanału wraz z możliwością kontroli temperatury gutaperki maksymalizując bezpieczeństwo.</p><p><strong>Endo-Mate DT – mikrosilnik endodontyczny</strong></p><p>Służy do opracowania światła kanału przy użyciu narzędzi mechanicznych. Pozwala dokładniej oczyścić kanał skracając jednocześnie czas zabiegu.</p><p><strong>Endometr Raypex</strong></p><p>Endometr jest cyfrowym urządzeniem służącym do badania długości kanałów korzeniowych w trakcie leczenia kanałowego. Ilustruje na „żywo” przesuwanie narzędzia endodontycznego wzdłuż całego kanału korzeniowego. Wykorzystanie endometru pozwala na dokładne wypełnienie kanału zęba, minimalizując powikłania wynikające z niedopełnienia lub przepełnienia kanału.</p><p><strong>Mikroskop zabiegowy</strong></p><p>Zastosowanie mikroskopu, czyli dużych powiększeń 6x, 10x, 16x, 25x w połączeniu z silniejszym, odpowiednio skupionym światłem pozwala na wykonywanie czynności, które bez jego wykorzystania nie byłyby możliwe .Umożliwia dostrzeżenie szczegółów niewidocznych podczas tradycyjnego leczenia endodontycznego oraz precyzyjną pracę dzięki trójwymiarowym obrazom o dużej głębi ostrości.</p><p><strong>Unit stomatologiczny</strong></p><p>Do Państwa dyspozycji mamy najnowszej generacji unit stomatologiczny firmy Stern Weber. Unit jest kompleksowo wyposażony, aby praca na nim była szybsza i przyjemniejsza dla pacjenta.</p>\t\t\t\t\t\t</div>\n</div>\n</div>\n</div>\n</div>\n</section>\n</div>\n<div class=\"post-tags\">\n</div>\n</div>\n";
